import { useNavigate } from 'react-router-dom';
import Navbar from '../components/Navbar';
import { FaUser, FaEnvelope, FaCalendar, FaTrophy, FaFire, FaClock, FaSignOutAlt, FaCamera, FaHeart, FaTrash, FaMars, FaVenus, FaUpload } from 'react-icons/fa';

function Profile() {
  const navigate = useNavigate();
  const [user, setUser] = useState({
    name: '',
    email: '',
    joined: '',
    avatar: null,
    avatarCategory: null
  });
  const [showAvatarPicker, setShowAvatarPicker] = useState(false);
  const [selectedCategory, setSelectedCategory] = useState(null);
  const [customImages, setCustomImages] = useState({
    boys: [],
    girls: []
  });

  // Import your custom images here
  // REPLACE THESE WITH YOUR ACTUAL IMAGE PATHS
  const boyAvatars = [
    { id: 1, path: require('../assets/avatars/boys/boy1.png'), name: 'Boy 1' },
    { id: 2, path: require('../assets/avatars/boys/boy2.png'), name: 'Boy 2' },
    { id: 3, path: require('../assets/avatars/boys/boy3.png'), name: 'Boy 3' },
    { id: 4, path: require('../assets/avatars/boys/boy4.png'), name: 'Boy 4' },
  ];

  const girlAvatars = [
    { id: 1, path: require('../assets/avatars/girls/girl1.png'), name: 'Girl 1' },
    { id: 2, path: require('../assets/avatars/girls/girl2.png'), name: 'Girl 2' },
    { id: 3, path: require('../assets/avatars/girls/girl3.png'), name: 'Girl 3' },
    { id: 4, path: require('../assets/avatars/girls/girl4.png'), name: 'Girl 4' },
  ];

  useEffect(() => {
    const savedAvatar = localStorage.getItem('userAvatar');
    const savedCategory = localStorage.getItem('userAvatarCategory');
    setUser({
      name: localStorage.getItem('userName') || 'User',
      email: localStorage.getItem('userEmail') || 'user@example.com',
      joined: new Date().toLocaleDateString(),
      avatar: savedAvatar,
      avatarCategory: savedCategory
    });
  }, []);

  const stats = [
    { icon: <FaFire color="#e74c3c" />, value: '12', label: 'Day Streak' },
    { icon: <FaTrophy color="#f39c12" />, value: '8', label: 'Badges Earned' },
    { icon: <FaClock color="#3498db" />, value: '245', label: 'Focus Minutes' },
    { icon: <FaHeart color="#e84393" />, value: '156', label: 'Moods Logged' },
  ];

  // Handle custom image upload
  const handleImageUpload = (event) => {
    const file = event.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const imageData = reader.result;
        setUser({ ...user, avatar: imageData, avatarCategory: 'custom' });
        localStorage.setItem('userAvatar', imageData);
        localStorage.setItem('userAvatarCategory', 'custom');
        setShowAvatarPicker(false);
      };
      reader.readAsDataURL(file);
    }
  };

  // Handle boy/girl avatar selection
  const handleAvatarSelect = (avatarPath, category) => {
    setUser({ ...user, avatar: avatarPath, avatarCategory: category });
    localStorage.setItem('userAvatar', avatarPath);
    localStorage.setItem('userAvatarCategory', category);
    setShowAvatarPicker(false);
    setSelectedCategory(null);
  };

  const handleLogout = () => {
    localStorage.removeItem('isLoggedIn');
    localStorage.removeItem('userName');
    localStorage.removeItem('userEmail');
    localStorage.removeItem('userAvatar');
    localStorage.removeItem('userAvatarCategory');
    navigate('/');
  };

  return (
    <div style={styles.container}>
      <Navbar />
      
      <div style={styles.content}>
        <div style={styles.header}>
          <h1 style={styles.title}>👤 Profile</h1>
          <p style={styles.subtitle}>Manage your account and view your progress</p>
        </div>

        {/* Avatar Card */}
        <div style={styles.avatarCard}>
          <div style={styles.avatarContainer}>
            {/* Avatar Display */}
            <div style={styles.avatarWrapper}>
              {user.avatar && (user.avatar.startsWith('data:image') || user.avatar.includes('blob')) ? (
                <img src={user.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : user.avatar && typeof user.avatar === 'string' && !user.avatar.startsWith('data:') ? (
                <img src={user.avatar} alt="Avatar" style={styles.avatarImage} />
              ) : (
                <div style={styles.avatarPlaceholder}>
                  <FaUser size={50} color="#ccc" />
                </div>
              )}
              
              {/* Edit Button */}
              <button 
                style={styles.editAvatarBtn}
                onClick={() => setShowAvatarPicker(!showAvatarPicker)}
              >
                <FaCamera size={16} />
              </button>
            </div>

            <h2 style={styles.userName}>{user.name}</h2>
            <div style={styles.userInfo}>
              <div style={styles.infoRow}><FaEnvelope /> {user.email}</div>
              <div style={styles.infoRow}><FaCalendar /> Joined {user.joined}</div>
            </div>
          </div>

          {/* Avatar Picker Popup */}
          {showAvatarPicker && (
            <div style={styles.avatarPicker}>
              <div style={styles.pickerHeader}>
                <h4>Choose Your Avatar</h4>
                <button onClick={() => setShowAvatarPicker(false)} style={styles.closeBtn}>✕</button>
              </div>
              
              {/* Upload Custom Image */}
              <div style={styles.uploadSection}>
                <label style={styles.uploadBtn}>
                  <FaUpload /> Upload Your Own Photo
                  <input
                    type="file"
                    accept="image/*"
                    onChange={handleImageUpload}
                    style={{ display: 'none' }}
                  />
                </label>
              </div>

              {/* Category Selection */}
              {!selectedCategory ? (
                <div style={styles.categoryGrid}>
                  <div style={styles.categoryCard} onClick={() => setSelectedCategory('boys')}>
                    <div style={styles.categoryIcon}><FaMars size={40} color="#3498db" /></div>
                    <h4>Boys</h4>
                    <p>Choose from boy avatars</p>
                  </div>
                  <div style={styles.categoryCard} onClick={() => setSelectedCategory('girls')}>
                    <div style={styles.categoryIcon}><FaVenus size={40} color="#e84393" /></div>
                    <h4>Girls</h4>
                    <p>Choose from girl avatars</p>
                  </div>
                </div>
              ) : (
                <>
                  <button 
                    onClick={() => setSelectedCategory(null)} 
                    style={styles.backBtn}
                  >
                    ← Back to Categories
                  </button>
                  <div style={styles.avatarGrid}>
                    {(selectedCategory === 'boys' ? boyAvatars : girlAvatars).map((avatar) => (
                      <div
                        key={avatar.id}
                        style={styles.avatarOption}
                        onClick={() => handleAvatarSelect(avatar.path, selectedCategory)}
                      >
                        <img src={avatar.path} alt={avatar.name} style={styles.avatarOptionImage} />
                        <span style={styles.avatarOptionName}>{avatar.name}</span>
                      </div>
                    ))}
                  </div>
                </>
              )}

              {/* Remove Avatar Option */}
              {user.avatar && (
                <button onClick={() => {
                  setUser({ ...user, avatar: null, avatarCategory: null });
                  localStorage.removeItem('userAvatar');
                  localStorage.removeItem('userAvatarCategory');
                  setShowAvatarPicker(false);
                }} style={styles.removeBtn}>
                  <FaTrash /> Remove Avatar
                </button>
              )}
            </div>
          )}
        </div>

        {/* Stats Grid */}
        <div style={styles.statsGrid}>
          {stats.map((stat, index) => (
            <div key={index} style={styles.statCard}>
              <div style={styles.statIcon}>{stat.icon}</div>
              <div style={styles.statValue}>{stat.value}</div>
              <div style={styles.statLabel}>{stat.label}</div>
            </div>
          ))}
        </div>

        {/* Menu Card */}
        <div style={styles.menuCard}>
          <h3 style={styles.menuTitle}>Settings</h3>
          <button onClick={handleLogout} style={styles.logoutBtn}>
            <FaSignOutAlt /> Logout
          </button>
        </div>
      </div>
    </div>
  );
}

const styles = {
  container: {
    minHeight: '100vh',
    background: 'linear-gradient(135deg, #667eea 0%, #764ba2 100%)',
  },
  content: {
    maxWidth: '600px',
    margin: '0 auto',
    padding: '20px',
    paddingTop: '80px',
  },
  header: {
    textAlign: 'center',
    marginBottom: '30px',
    color: 'white',
  },
  title: {
    fontSize: '32px',
    marginBottom: '10px',
  },
  subtitle: {
    fontSize: '14px',
    opacity: 0.9,
  },
  avatarCard: {
    background: 'white',
    borderRadius: '20px',
    padding: '30px',
    marginBottom: '20px',
    position: 'relative',
  },
  avatarContainer: {
    textAlign: 'center',
  },
  avatarWrapper: {
    position: 'relative',
    display: 'inline-block',
    marginBottom: '15px',
  },
  avatarImage: {
    width: '100px',
    height: '100px',
    borderRadius: '50%',
    objectFit: 'cover',
    border: '3px solid #667eea',
  },
  avatarPlaceholder: {
    width: '100px',
    height: '100px',
    borderRadius: '50%',
    background: '#f0f0f0',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    border: '3px solid #ccc',
  },
  editAvatarBtn: {
    position: 'absolute',
    bottom: '5px',
    right: '5px',
    background: '#667eea',
    color: 'white',
    border: 'none',
    width: '32px',
    height: '32px',
    borderRadius: '50%',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
  },
  userName: {
    fontSize: '24px',
    marginBottom: '10px',
    color: '#333',
  },
  userInfo: {
    color: '#666',
    fontSize: '14px',
  },
  infoRow: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    marginBottom: '5px',
  },
  avatarPicker: {
    position: 'absolute',
    top: '50%',
    left: '50%',
    transform: 'translate(-50%, -50%)',
    background: 'white',
    borderRadius: '20px',
    padding: '20px',
    width: '350px',
    maxHeight: '500px',
    overflowY: 'auto',
    boxShadow: '0 10px 40px rgba(0,0,0,0.2)',
    zIndex: 1000,
  },
  pickerHeader: {
    display: 'flex',
    justifyContent: 'space-between',
    alignItems: 'center',
    marginBottom: '15px',
  },
  closeBtn: {
    background: 'none',
    border: 'none',
    fontSize: '20px',
    cursor: 'pointer',
    color: '#999',
  },
  uploadSection: {
    marginBottom: '20px',
  },
  uploadBtn: {
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
    padding: '12px',
    background: '#667eea',
    color: 'white',
    borderRadius: '10px',
    cursor: 'pointer',
    textAlign: 'center',
  },
  categoryGrid: {
    display: 'grid',
    gridTemplateColumns: '1fr 1fr',
    gap: '15px',
    marginBottom: '20px',
  },
  categoryCard: {
    textAlign: 'center',
    padding: '20px',
    borderRadius: '15px',
    background: '#f8f9ff',
    cursor: 'pointer',
    transition: 'all 0.2s',
  },
  categoryIcon: {
    marginBottom: '10px',
  },
  backBtn: {
    background: 'none',
    border: 'none',
    color: '#667eea',
    cursor: 'pointer',
    marginBottom: '15px',
    fontSize: '14px',
  },
  avatarGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(2, 1fr)',
    gap: '15px',
    marginBottom: '20px',
  },
  avatarOption: {
    textAlign: 'center',
    padding: '10px',
    borderRadius: '10px',
    cursor: 'pointer',
    transition: 'all 0.2s',
  },
  avatarOptionImage: {
    width: '80px',
    height: '80px',
    borderRadius: '50%',
    objectFit: 'cover',
    marginBottom: '8px',
  },
  avatarOptionName: {
    fontSize: '12px',
    color: '#666',
  },
  removeBtn: {
    width: '100%',
    padding: '10px',
    background: '#e74c3c',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '8px',
  },
  statsGrid: {
    display: 'grid',
    gridTemplateColumns: 'repeat(2, 1fr)',
    gap: '15px',
    marginBottom: '20px',
  },
  statCard: {
    background: 'white',
    borderRadius: '15px',
    padding: '20px',
    textAlign: 'center',
  },
  statIcon: {
    fontSize: '28px',
    marginBottom: '10px',
  },
  statValue: {
    fontSize: '24px',
    fontWeight: 'bold',
    color: '#333',
  },
  statLabel: {
    fontSize: '12px',
    color: '#666',
  },
  menuCard: {
    background: 'white',
    borderRadius: '20px',
    padding: '20px',
  },
  menuTitle: {
    marginBottom: '15px',
    color: '#333',
  },
  logoutBtn: {
    width: '100%',
    padding: '12px',
    background: '#e74c3c',
    color: 'white',
    border: 'none',
    borderRadius: '10px',
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    gap: '10px',
    fontSize: '16px',
  },
};

export default Profile;
